// Exercise completion printing, native setup, and Bash dynamic suggestions.
import assert from 'node:assert/strict';
import { execFile } from 'node:child_process';
import { promisify } from 'node:util';
import {
  mkdtemp,
  readFile,
  writeFile,
  chmod,
  rm,
  readdir,
} from 'node:fs/promises';
import { join, resolve } from 'node:path';
import { tmpdir } from 'node:os';
import { gunzipSync } from 'node:zlib';
const execute = promisify(execFile);
const quote = value => `'${value.replace(/'/g, "'\\''")}'`;
const posix = value =>
  value
    .replace(/\\/g, '/')
    .replace(/^([a-z]):\//i, (_, drive) => `/${drive.toLowerCase()}/`);
const platform = `${process.platform === 'win32' ? 'win' : process.platform}-${process.arch}`;
const archive = await readFile(
  resolve(
    'dist-bin',
    `craft-${platform}${process.platform === 'win32' ? '.exe' : '.gz'}`,
  ),
);
const root = await mkdtemp(join(tmpdir(), 'craft setup smoke '));
try {
  const binary = join(
    root,
    process.platform === 'win32' ? 'craft.exe' : 'craft',
  );
  await writeFile(
    binary,
    process.platform === 'win32' ? archive : gunzipSync(archive),
  );
  await chmod(binary, 0o755);
  const env = {
    ...process.env,
    HOME: root,
    USERPROFILE: root,
    XDG_DATA_HOME: join(root, 'share'),
    XDG_CONFIG_HOME: join(root, 'config'),
    CRAFT_WORKSPACE: '',
    CRAFT_CONFIG: '',
    CRAFT_DRY_RUN: '',
    DRY_RUN: '',
    NODE_OPTIONS: '',
  };
  const run = (args, extra = {}) =>
    execute(binary, args, {
      cwd: root,
      env: { ...env, ...extra },
      timeout: 30000,
    });
  for (const shell of ['bash', 'zsh', 'fish']) {
    assert.match(
      (await run(['completion', shell])).stdout,
      /--get-yargs-completions/,
    );
    assert.match(
      (
        await execute(
          process.execPath,
          [resolve('packed/dist/craft'), 'completion', shell],
          { cwd: root, env },
        )
      ).stdout,
      /sentry-craft/,
    );
  }
  const files = await readdir(root);
  await run(['setup', '--shell', 'bash', '--dry-run']);
  assert.deepEqual(await readdir(root), files);
  const profile = join(root, '.bashrc');
  await writeFile(profile, 'user profile');
  await run(['setup', '--shell', 'bash']);
  const script = join(root, 'share/bash-completion/completions/craft');
  assert.match(await readFile(script, 'utf8'), /Generated by Craft/);
  assert.equal(await readFile(profile, 'utf8'), 'user profile');
  const completion = await execute(
    'bash',
    [
      '-c',
      `source ${quote(posix(script))}; COMP_WORDS=(${quote(posix(binary))} setup --in); COMP_CWORD=2; _craft_completion; printf '%s\\n' "\${COMPREPLY[@]}"`,
    ],
    { cwd: root, env },
  );
  assert(
    completion.stdout.split(/\r?\n/).includes('--install-dir'),
    `Missing --install-dir: ${completion.stdout}`,
  );
  assert(
    completion.stdout.split(/\r?\n/).includes('--install'),
    `Missing --install: ${completion.stdout}`,
  );
  const commands = (await run(['--get-yargs-completions', 'craft', ''])).stdout;
  assert.match(commands, /prepare/);
  assert.match(commands, /update/);
  console.log(
    `Completion generation, Bash suggestions, setup and dry-run verified: ${platform}`,
  );
} finally {
  await rm(root, { recursive: true, force: true });
}
